<script setup lang="ts">import {reactive} from 'vue';import Table from './common/Table.vue';import Status from './common/Status.vue';import {researchApi} from '../api/research';import {fmt} from '../utils/format';const props=defineProps<{runs:any[];user:any;reloadResearch:()=>Promise<void>}>();defineEmits(['open']);const busy=reactive<Record<number,boolean>>({});const failedRounds=(r:any)=>((r.attempt_history||[]) as any[]).filter(h=>h.phase==='failed');async function retry(r:any){if(busy[r.id])return;busy[r.id]=true;try{await researchApi.retryRun(r.id);await props.reloadResearch()}catch(e){alert((e as Error).message)}finally{busy[r.id]=false}}</script><template><Table :headers="['推断研究','状态 / 轮次','固定模型/轨迹数','总logL','打开 / 重试']"><tr v-for="r in runs" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}} / 研究{{r.study_id}}</small></td><td><Status :value="r.status"/><small>第 {{r.attempt_no||1}} 轮 · 共 {{(r.attempt_history||[]).filter((h:any)=>h.phase==='retry').length}} 次重试</small><small v-if="r.error" class="copper">{{r.error}}</small><details v-if="failedRounds(r).length>0"><summary>逐轮错误与重试记录（{{failedRounds(r).length}} 次失败）</summary><ul class="attempt-log"><li v-for="h in r.attempt_history" :key="h.attempt+'-'+h.phase+'-'+h.at"><small>{{h.at}} · 第{{h.attempt}}轮 · {{h.phase}}<template v-if="h.retried_by"> · {{h.retried_by}}</template><span v-if="h.error" class="copper">：{{h.error}}</span></small></li></ul></details></td><td>{{r.profile_snapshot.name}}<small>{{r.trace_snapshot.length}}条 · 快照已冻结</small></td><td>{{r.total_log_likelihood===null?'—':fmt(r.total_log_likelihood,5)}}</td><td><button @click="$emit('open',r)">展开隐态 ↗</button><button v-if="r.status==='failed'&&user.role!=='viewer'" class="retry-btn" :disabled="busy[r.id]" @click="retry(r)">{{busy[r.id]?'重新排队中…':'原地重试（沿用冻结快照）↻'}}</button><small v-if="r.status==='failed'&&user.role==='viewer'" class="copper">失败运行可由分析员原地重试</small></td></tr></Table></template>
